const CODE_SAMPLE=`"""Static planar image placement example (offline, single frame).\n\nThis is a generated starter, not a validated AR/tracking system. Supply four\nmeasured surface corners in the input frame, ordered TL, TR, BR, BL.\n\nExample:\npython surface_overlay_demo.py --frame frame.jpg --image overlay.png \\\n  --corners 120,80 620,90 610,390 110,370 --out preview.jpg\n"""\nimport argparse\nimport cv2\nimport numpy as np\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument('--frame', required=True, help='Still image of the surface')\n    parser.add_argument('--image', required=True, help='Overlay image (PNG alpha supported)')\n    parser.add_argument('--corners', nargs=4, required=True, metavar=('TL','TR','BR','BL'),\n                        help='Four frame pixel points, each as x,y')\n    parser.add_argument('--out', default='surface_overlay_preview.jpg')\n    args = parser.parse_args()\n\n    frame = cv2.imread(args.frame, cv2.IMREAD_COLOR)\n    overlay = cv2.imread(args.image, cv2.IMREAD_UNCHANGED)\n    if frame is None or overlay is None:\n        raise SystemExit('Could not read --frame or --image')\n    points = np.array([[float(v) for v in p.split(',')] for p in args.corners],\n                      dtype=np.float32)\n    h, w = overlay.shape[:2]\n    source = np.array([[0, 0], [w-1, 0], [w-1, h-1], [0, h-1]], dtype=np.float32)\n    H = cv2.getPerspectiveTransform(source, points)\n    warped = cv2.warpPerspective(overlay, H, (frame.shape[1], frame.shape[0]))\n    mask = cv2.warpPerspective(np.full((h, w), 255, np.uint8), H,\n                               (frame.shape[1], frame.shape[0]))\n    if warped.ndim == 3 and warped.shape[2] == 4:\n        alpha = warped[:, :, 3].astype(np.float32) / 255.0\n        alpha *= (mask > 0).astype(np.float32)\n        color = warped[:, :, :3].astype(np.float32)\n    else:\n        alpha = (mask > 0).astype(np.float32) * 0.65\n        color = warped.astype(np.float32)\n    result = (frame.astype(np.float32) * (1-alpha[..., None]) +\n              color * alpha[..., None]).clip(0, 255).astype(np.uint8)\n    cv2.polylines(result, [points.astype(np.int32)], True, (0, 220, 180), 2)\n    if not cv2.imwrite(args.out, result):\n        raise SystemExit('Could not write output image')\n    print(f'Wrote {args.out}; point coordinates are user-supplied, not detected.')\n\nif __name__ == '__main__':\n    main()\n`;
