const DBKEY='fv_opencv_surface_placement_v1';let db=loadDB(),page='overview',searchText='',statusFilter='All',editId=null,editType=null;
function loadDB(){try{const saved=JSON.parse(localStorage.getItem(DBKEY));if(saved&&saved.records)return saved}catch(e){}const fresh={records:SEED,history:[{date:new Date().toISOString(),event:'Workspace initialized',detail:'Seeded research context and proposed validation workflow.'}]};localStorage.setItem(DBKEY,JSON.stringify(fresh));return fresh}
function persist(msg='Saved locally'){db.updatedAt=new Date().toISOString();localStorage.setItem(DBKEY,JSON.stringify(db));const el=document.getElementById('saveState');if(el)el.textContent=msg;}
function allRecords(){return Object.values(db.records).flat()}function byType(type){return db.records[type]||[]}function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function title(r){return r.title||r.name||'Untitled record'}function badge(s){let c=(s||'Unknown').toLowerCase().replaceAll(' ','-');return `<span class="status ${safe(c)}">${safe(s||'Unknown')}</span>`}function fmtDate(d){return d?new Date(d).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'Not recorded'}function recordCount(types){return types.reduce((n,t)=>n+byType(t).length,0)}
function renderNav(){document.getElementById('navigation').innerHTML=NAV.map(([id,icon,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}<span class="nav-count">${id==='overview'?'':countForNav(id)}</span></button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));}
function countForNav(id){const map={research:['paper','research'],setup:['marker','environment','camera','target','calibration'],methods:['model','code'],experiments:['experiment'],validation:['validation'],compare:[],sources:['source','evidence'],exports:['action']};return recordCount(map[id]||[])}
function go(p){page=p;searchText='';statusFilter='All';renderNav();renderPage();document.getElementById('sidebar').classList.remove('open');window.scrollTo(0,0)}function head(kicker,h,sub,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${h}</h1><p>${sub}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`}function addBtn(type,label){return `<button class="button button-primary" data-add="${type}">＋ ${label||'Add record'}</button>`}
function renderPage(){const c=document.getElementById('content');const views={overview:renderOverview,research:renderResearch,setup:renderSetup,methods:renderMethods,experiments:renderExperiments,validation:renderValidation,compare:renderCompare,sources:renderSources,exports:renderExports};c.innerHTML=(views[page]||renderOverview)();bindPage();}
function renderOverview(){const total=allRecords().length,validated=byType('validation').filter(x=>x.status==='Verified').length,planned=allRecords().filter(x=>['Proposed','Pending','TBD','Unknown'].includes(x.status)).length;return `${head('WORKSPACE / OVERVIEW','Surface image placement, with evidence.','A structured lab notebook for registering an environment surface and validating image placement.')}<section class="hero"><div class="hero-copy"><span class="eyebrow">OPENCV · RESEARCH → MEASUREMENT</span><h2>Give every overlay a coordinate frame.</h2><p>Track indicators, cameras, surfaces, transforms, and run evidence in one place. Findings from papers stay separate from measured results.</p><div class="hero-meta"><span class="tag">${total} records</span><span class="tag warn">No live setup verified</span><span class="tag">Local-first</span></div></div><div class="hero-visual"><svg viewBox="0 0 250 165" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M55 24 210 47 182 143 26 118Z" stroke="#696a6e" stroke-width="1.2"/><path d="m55 24 5 12m-5-12 12-5M210 47l-13 4m13-4-4 13M182 143l-5-13m5 13-13 5M26 118l13-4m-13 4 4-13" stroke="#d7d9dd" stroke-width="2"/><path d="m72 47 116 17-18 60-116-17Z" fill="#4f5054" fill-opacity=".45" stroke="#b4b5b9" stroke-dasharray="4 4"/><path d="m88 59 77 11-12 38-77-11Z" fill="#d7d9dd" fill-opacity=".13" stroke="#d7d9dd"/><circle cx="72" cy="47" r="3" fill="#d7d9dd"/><circle cx="188" cy="64" r="3" fill="#d7d9dd"/><circle cx="170" cy="124" r="3" fill="#d7d9dd"/><circle cx="54" cy="107" r="3" fill="#d7d9dd"/><path d="M5 151h70m-70 0 5-4m-5 4 5 4" stroke="#8a8b8f"/><text x="81" y="155" fill="#afb0b4" font-size="9" font-family="monospace">X / SURFACE PLANE</text></svg></div></section><div class="metric-grid"><div class="metric"><div class="metric-label">Workspace records</div><div class="metric-value">${total}</div><div class="metric-note">Across research, setup, runs, sources</div></div><div class="metric"><div class="metric-label">Research sources</div><div class="metric-value teal">${recordCount(['paper','source'])}</div><div class="metric-note">All source claims remain citation-linked</div></div><div class="metric"><div class="metric-label">Verified validation</div><div class="metric-value">${validated}</div><div class="metric-note">Only measured checks marked Verified</div></div><div class="metric"><div class="metric-label">Open / unconfirmed</div><div class="metric-value">${planned}</div><div class="metric-note">Proposed · Pending · TBD · Unknown</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h3>Placement pipeline</h3><small>GUIDED WORKFLOW</small></div><div class="pipeline"><div class="pipeline-step current"><b>01 / DEFINE</b><p>Surface plane, dimensions, origin, units.</p></div><div class="pipeline-step"><b>02 / CALIBRATE</b><p>Camera intrinsics and lens distortion.</p></div><div class="pipeline-step"><b>03 / LOCALIZE</b><p>Marker, features, geometry, homography or pose.</p></div><div class="pipeline-step"><b>04 / VALIDATE</b><p>Overlay error, stability, occlusion, evidence.</p></div></div><div class="callout green" style="margin-top:16px"><b>Current first outcome:</b> define one planar surface, attach a known target image, then establish a static four-corner mapping baseline. No live camera result has been recorded.</div></section><section class="panel"><div class="panel-head"><h3>Research context</h3><small>FROM LIBRARY BRIEF · REV A</small></div><div class="research-note"><strong>Prior research note:</strong> A planar marker board is proposed for initialization. The earlier brief described a synthetic NFL-style down-marker exercise for object tracking; it does not establish full-field registration. The NBA paper title remains Unknown.</div><div class="list" style="margin-top:7px"><div class="list-row"><span class="list-mark">⌖</span><div><b>Starter protocol is proposed</b><small>Viewpoint change · lighting · partial occlusion · marker loss/reacquisition</small></div></div><div class="list-row"><span class="list-mark">↗</span><div><b>Basketball and field papers indexed</b><small>Research references; no experimental claim imported</small></div></div></div></section></div><div class="dashboard-grid" style="margin-top:15px"><section class="panel"><div class="panel-head"><h3>Next actions</h3><button class="text-link" data-page="exports">Open action queue →</button></div>${actionList()}</section><section class="panel"><div class="panel-head"><h3>Trust labels</h3><small>RECORD-LEVEL STATUS</small></div><div class="status-guide">${['Proposed','Pending','Verified','TBD','Unknown'].map(s=>`<div class="status-item">${badge(s)}<p>${({Proposed:'Suggested design or method; not run.',Pending:'Awaiting evidence, review, or action.',Verified:'Measured or confirmed with attached evidence.',TBD:'A decision or value remains to be set.',Unknown:'No source value is currently known.'})[s]}</p></div>`).join('')}</div></section></div>`}
function actionList(){return `<div class="list">${byType('action').slice(0,4).map(r=>`<div class="list-row" data-detail="${r.id}" data-type="action"><span class="list-mark">${r.kind==='Blocker'?'!':'→'}</span><div style="flex:1"><b>${safe(r.title)}</b><small>${safe(r.details||'')}</small></div>${badge(r.status)}</div>`).join('')}</div>`}
function tableView(types,cols){const rows=types.flatMap(t=>byType(t)).filter(r=>(!searchText||JSON.stringify(r).toLowerCase().includes(searchText.toLowerCase()))&&(statusFilter==='All'||r.status===statusFilter));return `<div class="toolbar"><label class="search"><span>⌕</span><input id="recordSearch" placeholder="Search records…" value="${safe(searchText)}" /></label><select class="filter-select" id="statusFilter"><option>All</option>${STATUS.map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select><span class="count">${rows.length} RECORDS</span></div><div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(x=>`<th>${x[0]}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr data-detail="${r.id}" data-type="${r.type}">${cols.map((x,i)=>`<td>${i===0?`<span>${safe(r[x[1]]||title(r))}</span><span class="subcell">${safe(r[x[2]]||r.type)}</span>`:x[1]==='status'?badge(r.status):safe(r[x[1]]||'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="empty">No records match. Add a record or change the filter.</td></tr>`}</tbody></table></div>`}
function renderResearch(){return `${head('KNOWLEDGE BASE','Research & papers','Record source-backed findings separately from experiment observations.',addBtn('research','Add finding')+addBtn('paper','Add paper'))}<div class="callout" style="margin-bottom:14px">Research findings describe literature or design rationale. They do not count as experimentally verified results. Use citations in Sources & evidence and link claims back to the source record.</div><div class="panel" style="margin-bottom:14px"><div class="panel-head"><h3>Research findings</h3><small>${byType('research').length} FINDINGS</small></div>${tableView(['research'],[['Finding','title','method'],['Summary','summary','source'],['Status','status','']])}</div><div class="panel"><div class="panel-head"><h3>Sports and OpenCV references</h3><small>NBA / NFL REFERENCE TRACKING</small></div>${tableView(['paper'],[['Reference','title','sport'],['Publication','publication','authors'],['Status','status','']])}</div>`}
function renderSetup(){return `${head('PHYSICAL SETUP','Environments & setup','Define real surfaces, cameras, indicators, target geometry, and calibration records.',addBtn('environment','Add environment'))}<div class="split"><section class="panel"><div class="panel-head"><h3>Sample environments</h3>${addBtn('environment','＋')}</div>${cards('environment')}</section><section class="panel"><div class="panel-head"><h3>Indicators / markers</h3>${addBtn('marker','＋')}</div>${cards('marker')}</section><section class="panel"><div class="panel-head"><h3>Surface cameras</h3>${addBtn('camera','＋')}</div>${cards('camera')}</section><section class="panel"><div class="panel-head"><h3>Placement targets</h3>${addBtn('target','＋')}</div>${cards('target')}</section><section class="panel" style="grid-column:1/-1"><div class="panel-head"><h3>Calibration inputs</h3>${addBtn('calibration','＋')}</div>${tableView(['calibration'],[['Record','name','camera'],['Pattern','pattern','imageCount'],['Reprojection','reprojection','evidence'],['Status','status','']])}</section></div>`}
function cards(type){return `<div class="card-grid">${byType(type).map(r=>`<article class="record-card" data-detail="${r.id}" data-type="${type}"><div class="record-card-head"><h3>${safe(title(r))}</h3>${badge(r.status)}</div><p>${safe(r.notes||r.summary||r.dimensions||r.physicalSize||'No notes recorded.')}</p><div class="record-card-foot"><span>${safe(r.class||r.type||r.unit||'Record')}</span><span>Open →</span></div></article>`).join('')}</div>`}
function renderMethods(){return `${head('IMPLEMENTATION','Models & code','Version transforms and reproducible examples, including inputs, dependencies, commands, and expected output.',addBtn('code','Add runnable example')+addBtn('model','Add method'))}<div class="callout" style="margin-bottom:14px">Runnable status is record metadata. A code record is not runnable until its source, dependencies, inputs, command, and execution evidence have been checked.</div><div class="panel" style="margin-bottom:14px"><div class="panel-head"><h3>Models & placement methods</h3><small>VERSIONED COMPONENTS</small></div>${tableView(['model'],[['Method','name','method'],['Version','version','pipelineStage'],['Inputs / parameters','inputs','parameters'],['Status','status','runtime']])}</div><div class="panel"><div class="panel-head"><h3>Runnable examples</h3><small>EXECUTION METADATA</small></div><div class="card-grid">${byType('code').map(r=>`<article class="record-card" data-detail="${r.id}" data-type="code"><div class="record-card-head"><h3>${safe(r.name)}</h3>${badge(r.status)}</div><p>${safe(r.expected||'Expected output not recorded')}</p><div class="record-card-foot"><span>${safe(r.language)} · ${safe(r.version)}</span><span>Inspect →</span></div></article>`).join('')}</div><div style="margin-top:14px"><div class="panel-head"><div><h3>Generated sample code</h3><small>STATIC FRAME · MANUAL CORNERS · NOT RUN OR VERIFIED</small></div><button class="button" data-download-code>Download .py</button></div><pre class="inline-code">${safe(CODE_SAMPLE)}</pre></div></div>`}
function renderExperiments(){return `${head('TEST LOG','Experiment runs','Store conditions, ground truth, observations, and per-frame metrics for each capture.',addBtn('experiment','New experiment run'))}<div class="callout green" style="margin-bottom:14px"><b>Research proposal only:</b> starter protocol covers frontal and oblique views, lighting change, partial/full marker occlusion, and reacquisition. Capture no result as Verified until the run has evidence and measured outcomes.</div>${tableView(['experiment'],[['Experiment','title','environment'],['Test condition','condition','camera'],['Observations','observations','metrics'],['Status','status','date']])}`}
function renderValidation(){return `${head('MEASUREMENT','Validation results','Compare observed measurements with explicit criteria. Mark Verified only when evidence supports the result.',addBtn('validation','Add validation result'))}<div class="callout" style="margin-bottom:14px">Suggested targets below came from the prior research brief. They are proposals and must be revisited after camera resolution, distance, and operating range are selected.</div>${tableView(['validation'],[['Check','title','run'],['Metric / unit','metric','criterion'],['Criterion','criterion','sampleSize'],['Measured result','result','method'],['Status','status','evidence']])}`}
function renderCompare(){const rows=[['Coded fiducial','Marker ID + known geometry','Controlled prototype; rapid initialization','Visible marker, print scale, pixels and contrast','High','Medium'],['Marker board','Several known markers in a measured layout','Larger target plane; possible partial marker loss','Board geometry and visibility still matter','High','Medium'],['Natural features','Distinctive surface texture','Existing textured objects or surfaces','Weak on plain, glossy, repetitive or changing areas','Medium','Low'],['Sports geometry','Known court/field lines and landmarks','Sports courts and fields','Repeated lines, moving occlusion, camera cuts','Medium','High'],['Hybrid','Fiducial initialization + geometric/feature updates','Potential continuation after marker initialization','More logic; reconcile estimates and confidence','High','High']];return `${head('METHOD SELECTION','Compare approaches','Compare candidate indicators and mapping strategies before selecting a test.',addBtn('model','Record selected method'))}<div class="callout green" style="margin-bottom:14px">Ratings are qualitative research-planning prompts from the prior brief, not measured scores. Replace with run-specific metrics once tested.</div><div class="table-wrap"><table class="comparison"><thead><tr><th>Candidate</th><th>Indicator / cue</th><th>Best fit</th><th>Main limitation to test</th><th>Setup</th><th>Occlusion tolerance</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td>${i>3?`<span class="score"><i style="width:${c==='High'?'82%':'50%'}"></i></span>${c}`:safe(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><section class="panel" style="margin-top:14px"><div class="panel-head"><h3>Placement methods to compare</h3><small>PLANAR / NON-PLANAR</small></div><div class="split"><div><b style="font-size:11px">Homography · planar</b><p class="detail-desc">Four or more correspondences between a surface template and camera pixels. Log inlier count and reprojection error; test corner and interior-point alignment.</p></div><div><b style="font-size:11px">Pose / 3D model · non-planar extensions</b><p class="detail-desc">Use calibrated camera intrinsics and known 3D geometry, or multiple local surface patches. A single planar homography is not a general non-planar solution.</p></div></div></section>`}
function renderSources(){return `${head('EVIDENCE REGISTER','Sources & evidence','Keep citations, source claims, screenshots, code, calibration files, and run artifacts attached to records.',addBtn('source','Add citation')+addBtn('evidence','Add evidence'))}<div class="panel" style="margin-bottom:14px"><div class="panel-head"><h3>Citations & source tracking</h3><small>${byType('source').length} SOURCES</small></div>${tableView(['source'],[['Source','title','authors'],['Type / topic','sourceType','sport'],['Year','year','citation'],['Status','status','url']])}</div><div class="panel"><div class="panel-head"><h3>Evidence register</h3><small>${byType('evidence').length} ATTACHMENTS</small></div>${byType('evidence').length?tableView(['evidence'],[['Evidence','title','kind'],['Related record','related','location'],['What it shows','description','location'],['Status','status','location']]):'<div class="empty">No evidence files have been attached. Add a record with a filename or URI; uploads and cloud storage are not configured.</div>'}</div>`}
function renderExports(){return `${head('PORTABILITY','Exports & history','Download structured records for Microsoft Excel, review a Markdown brief, or bundle a ZIP handoff.',addBtn('action','Add action / blocker'))}<section class="panel" style="margin-bottom:14px"><div class="panel-head"><h3>Export package</h3><small>RESEARCH AND RESULTS REMAIN DISTINGUISHED</small></div><div class="export-grid"><div class="export-card"><span class="export-icon">XLS</span><h3>Excel-ready workbook data</h3><p>Download CSV tables by record type. Open directly in Microsoft Excel; statuses and units are preserved as fields.</p><button class="button" data-export="csv">Export CSV set</button></div><div class="export-card"><span class="export-icon">{ }</span><h3>JSON data package</h3><p>Full record set, status values, workspace metadata, and revision history.</p><button class="button" data-export="json">Download JSON</button></div><div class="export-card"><span class="export-icon">MD</span><h3>Markdown research brief</h3><p>Readable snapshot of findings, sources, runs, validation, blockers, and open unknowns.</p><button class="button" data-export="md">Download Markdown</button></div><div class="export-card"><span class="export-icon">PDF</span><h3>Print / PDF view</h3><p>Open the browser print dialog to save the current workspace view as PDF.</p><button class="button" data-export="pdf">Print workspace</button></div><div class="export-card"><span class="export-icon">ZIP</span><h3>Complete handoff ZIP</h3><p>Bundle JSON, Markdown, and Excel-ready CSV tables. Evidence files are referenced by URI and are not copied.</p><button class="button" data-export="zip">Download ZIP package</button></div><div class="export-card"><span class="export-icon">LOG</span><h3>Proposed integrations</h3><p>Database, external integrations, and package storage are tracked as records; none are configured.</p><button class="button" data-add="action">＋ Track a proposal</button></div></div></section><div class="split"><section class="panel"><div class="panel-head"><h3>Blockers & next actions</h3><small>${byType('action').length} ITEMS</small></div>${actionList()}</section><section class="panel"><div class="panel-head"><h3>Revision history</h3><small>LOCAL EDIT LOG</small></div>${db.history.slice().reverse().slice(0,8).map(h=>`<div class="revision"><span class="revision-mark">↻</span><div><b>${safe(h.event)}</b><small>${safe(h.detail)} · ${fmtDate(h.date)}</small></div></div>`).join('')}</section></div>`}
function bindPage(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>openDetail(el.dataset.type,el.dataset.detail));const sr=document.getElementById('recordSearch');if(sr){sr.oninput=()=>{searchText=sr.value;const pos=sr.selectionStart;renderPage();const n=document.getElementById('recordSearch');n.focus();n.setSelectionRange(pos,pos)}}const sf=document.getElementById('statusFilter');if(sf)sf.onchange=()=>{statusFilter=sf.value;renderPage()};document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportAs(b.dataset.export));const dl=document.querySelector('[data-download-code]');if(dl)dl.onclick=()=>download('surface_overlay_demo.py',new Blob([CODE_SAMPLE],{type:'text/x-python'}));}
function openForm(type,record=null){editId=record?.id||null;editType=type;const schema=TYPES[type];document.getElementById('dialogTitle').textContent=(record?'Edit ':'Add ')+schema.label;const fields=schema.fields;document.getElementById('formFields').innerHTML=fields.map(([key,label,kind='text',required=false,options])=>{let value=record?.[key]??(key==='status'?'Proposed':'');let control='';if(kind==='textarea')control=`<textarea name="${key}" ${required?'required':''}>${safe(value)}</textarea>`;else if(kind==='select'||kind==='status'){const opts=kind==='status'?STATUS:options;control=`<select name="${key}">${(kind==='status'?opts:['',...opts]).map(o=>`<option value="${safe(o)}" ${value===o?'selected':''}>${safe(o||'Select…')}</option>`).join('')}</select>`}else control=`<input name="${key}" type="${kind}" value="${safe(value)}" ${required?'required':''} />`;return `<div class="field ${kind==='textarea'?'full':''}"><label>${safe(label)}${required?' *':''}</label>${control}</div>`}).join('');document.getElementById('recordDialog').showModal()}
function saveForm(e){e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form).entries());if(editId){for(const r of byType(editType)){if(r.id===editId)Object.assign(r,data)}addHistory('Record updated',title(data))}else{data.id='rec-'+crypto.randomUUID();data.type=editType;(db.records[editType]??=[]).unshift(data);addHistory('Record added',`${TYPES[editType].label}: ${title(data)}`)}persist();document.getElementById('recordDialog').close();renderPage();toast('Record saved locally')}
function addHistory(event,detail){db.history.push({date:new Date().toISOString(),event,detail})}
function openDetail(type,id){const r=byType(type).find(x=>x.id===id);if(!r)return;const fields=TYPES[type]?.fields||[];document.getElementById('detailContent').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${safe(TYPES[type]?.label||type)}</span><h2 class="detail-title">${safe(title(r))}</h2></div><button type="button" class="icon-button" id="closeDetail">×</button></div><div class="detail-desc">${safe(r.summary||r.finding||r.details||r.notes||'')}</div><div style="margin-top:12px">${badge(r.status)}</div><div class="detail-grid">${fields.filter(f=>r[f[0]]).map(f=>`<div class="detail-field"><label>${safe(f[1])}</label><span>${f[0]==='url'&&r[f[0]]?`<a class="source-url" href="${safe(r[f[0]])}" target="_blank" rel="noreferrer">${safe(r[f[0]])}</a>`:safe(r[f[0]])}</span></div>`).join('')}</div><div class="detail-actions"><button class="button" id="editRecord">Edit record</button><button class="button" id="deleteRecord">Delete</button></div>`;document.getElementById('detailDialog').showModal();document.getElementById('closeDetail').onclick=()=>document.getElementById('detailDialog').close();document.getElementById('editRecord').onclick=()=>{document.getElementById('detailDialog').close();openForm(type,r)};document.getElementById('deleteRecord').onclick=()=>{if(confirm('Delete this record?')){db.records[type]=byType(type).filter(x=>x.id!==id);addHistory('Record deleted',title(r));persist();document.getElementById('detailDialog').close();renderPage();toast('Record deleted')}}}
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}function csvEscape(v){return '"'+String(v??'').replaceAll('"','""')+'"'}function csvFor(type){const rows=byType(type);const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];return [keys.map(csvEscape).join(','),...rows.map(r=>keys.map(k=>csvEscape(r[k])).join(','))].join('\r\n')}
function packageObj(){return {workspace:'OpenCV Surface Placement Workbench',schemaVersion:'1.0',createdAt:'2026-11-17',updatedAt:db.updatedAt||null,localOnly:true,records:db.records,revisionHistory:db.history,notes:{researchVsValidation:'Research findings are separate from experimentally measured results.',storage:'No database, external integration, or package storage is configured.',units:'Consumer-product geometry: mm. Industrial components: in.'}}}
function markdown(){let out=`# OpenCV Surface Placement Workbench\n\nGenerated ${new Date().toLocaleString()} · Local workspace snapshot\n\n> Research findings and experimentally measured results are separate. Statuses are record-level.\n\n## Summary\n\n- Records: ${allRecords().length}\n- Verified validation checks: ${byType('validation').filter(r=>r.status==='Verified').length}\n- Sources: ${byType('source').length}\n- Experiment runs: ${byType('experiment').length}\n\n`;for(const [label,types] of [['Research findings',['research']],['Sports and OpenCV references',['paper']],['Environments / markers / cameras / targets',['environment','marker','camera','target','calibration']],['Methods and runnable examples',['model','code']],['Experiment runs',['experiment']],['Validation results',['validation']],['Citations',['source']],['Evidence',['evidence']],['Actions / blockers',['action']]]){out+=`## ${label}\n\n`;for(const t of types)for(const r of byType(t)){out+=`### ${title(r)} · ${r.status||'Unknown'}\n\n`;for(const f of (TYPES[t]?.fields||[])){const [k,l]=f;if(r[k]&&k!=='title'&&k!=='name')out+=`- **${l}:** ${r[k]}\n`}if(!Object.keys(r).some(k=>k!=='id'&&k!=='type'&&k!=='status'&&r[k]))out+='- No details recorded.\n';out+='\n'}}out+='## Revision history\n\n'+db.history.map(h=>`- ${fmtDate(h.date)} — **${h.event}:** ${h.detail}`).join('\n')+'\n';return out}
function exportAs(kind){if(kind==='json')download('opencv_surface_placement_workspace.json',new Blob([JSON.stringify(packageObj(),null,2)],{type:'application/json'}));if(kind==='md')download('opencv_surface_placement_brief.md',new Blob([markdown()],{type:'text/markdown'}));if(kind==='csv'){for(const t of Object.keys(db.records))if(byType(t).length)download(`opencv_${t}.csv`,new Blob(['\ufeff'+csvFor(t)],{type:'text/csv;charset=utf-8'}));}if(kind==='pdf'){window.print()}if(kind==='zip')download('opencv_surface_placement_handoff.zip',new Blob([zipFiles([['workspace.json',JSON.stringify(packageObj(),null,2)],['research_brief.md',markdown()],['code/surface_overlay_demo.py',CODE_SAMPLE],...Object.keys(db.records).filter(t=>byType(t).length).map(t=>[`csv/opencv_${t}.csv`,'\ufeff'+csvFor(t)])])],{type:'application/zip'}));toast(kind==='pdf'?'Print dialog opened':`Exported ${kind.toUpperCase()}`)}
// Small store-only ZIP writer (UTF-8, no compression) for portable browser handoffs.
const crcTable=(()=>{let c,t=[];for(let n=0;n<256;n++){c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();function crc32(buf){let c=-1;for(const b of buf)c=crcTable[(c^b)&255]^(c>>>8);return(c^-1)>>>0}function u16(n){return[n&255,(n>>>8)&255]}function u32(n){return[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}function zipFiles(files){const enc=new TextEncoder();let local=[],central=[],offset=0;for(const [name,content] of files){const n=enc.encode(name),d=enc.encode(content),crc=crc32(d),lh=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...n,...d]);local.push(lh);const ch=new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...n]);central.push(ch);offset+=lh.length}const centralSize=central.reduce((a,x)=>a+x.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(files.length),...u16(files.length),...u32(centralSize),...u32(offset),...u16(0)]);return new Blob([...local,...central,end])}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
document.getElementById('recordForm').addEventListener('submit',saveForm);document.getElementById('closeDialog').onclick=()=>document.getElementById('recordDialog').close();document.getElementById('cancelDialog').onclick=()=>document.getElementById('recordDialog').close();document.getElementById('quickAdd').onclick=()=>{const t=prompt('Choose a record type: research, paper, marker, environment, camera, target, calibration, model, code, experiment, validation, source, evidence, action');if(t&&TYPES[t.trim().toLowerCase()])openForm(t.trim().toLowerCase());else if(t)toast('Type not found. Use the section Add buttons.')};document.getElementById('menuToggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');renderNav();renderPage();
